    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Homestay da LSI: as famílias são selecionadas pelos Accommodation Officers da própria escola e visitadas com regularidade. Você pode escolher quarto individual (ou twin, quando duas pessoas reservam para o mesmo período) com café da manhã ou meia pensão. Roupa de cama e toalhas são fornecidas e trocadas semanalmente e o anfitrião oferece pelo menos uma lavagem de roupa por semana sem custo. Quem reserva só com café da manhã normalmente não tem acesso à cozinha. Há a opção Executive, com banheiro privativo (ensuite ou de uso exclusivo), mediante suplemento. Em San Diego, as famílias oferecem a experiência do estilo de vida californiano; os trajetos até a escola variam de 45 a 60 minutos e há lavanderia na casa ou em lavanderias locais por cerca de 5 dólares. Nesta opção o quarto é duplo/twin (para quem viaja acompanhado ou dividido com outro estudante do mesmo gênero) e o banheiro é compartilhado. O regime é de meia pensão, com café da manhã e jantar inclusos; o almoço fica por sua conta.</p><p>Suplementos e condições: Suplemento de alta temporada: USD 40/semana (14/jun a 23/ago); Suplemento dieta especial: USD 50/semana; Outro suplemento: USD 60.</p><p>Suplementos da casa de família em LSI San Diego, por pessoa por semana: verão de 14/jun a 23/ago US$40; Natal (fins de semana de 26-27/dez e 2-3/jan) US$60; dieta especial US$25 com café da manhã e US$50 com meia pensão; quarto executivo com banheiro privativo US$90; menores de 18 anos US$20. Taxa de colocação da acomodação US$160. Taxa de inscrição da escola US$185, envio de documentos por courier US$100, seguro-saúde US$40 por semana, transfer do aeroporto US$170 somente ida. Chegadas e saídas de sábado a sábado ou de domingo a domingo. Os preços da acomodação podem mudar ao longo do ano — confirme com a LSI San Diego na hora da reserva. Fonte: LSI Prices and Dates 2026.</p>','["Famílias Selecionadas e Visitadas pela Escola", "Roupa de Cama e Toalhas Trocadas Semanalmente", "1 Lavagem de Roupa por Semana Inclusa", "Quarto Individual ou Twin", "Imersão Cultural", "Prática Diária de Inglês", "Opção Executive com Banheiro Privativo", "Chegadas aos Sábados ou Domingos", "Quarto Duplo/Twin", "Banheiro Compartilhado", "Meia Pensão", "Ideal para quem quer imersão cultural e prática diária de inglês", "Ideal para quem prefere ter refeições resolvidas em casa", "Ideal para quem viaja sozinho e quer apoio de anfitriões locais", "Ideal para quem busca bom custo-benefício com serviços inclusos", "Ideal para quem viaja acompanhado ou quer dividir custos", "Ideal para quem gosta de socializar e não se importa em dividir espaços", "Ideal para quem quer café da manhã e jantar garantidos e economia no dia a dia"]'::jsonb,'["Menos indicado para quem quer cozinhar livremente (sobretudo no regime só com café da manhã)", "Menos indicado para quem precisa morar a poucos minutos da escola", "Menos indicado para quem quer liberdade total de horários e visitas", "Menos indicado para quem prefere a vida social de uma residência estudantil", "Menos indicado para quem precisa de privacidade e silêncio", "Menos indicado para quem faz questão de banheiro exclusivo", "Menos indicado para quem tem horários irregulares e prefere jantar fora com frequência"]'::jsonb);
    insert into price_template (tenant_id, campus_id, name, price_basis, duration_type, unit, currency, charge_in_tiers, valid_from, status) values (v_tid,'4ff6d931-c7ac-5bcc-948a-0d3208e0c571','Casa de família — quarto compartilhado, banheiro compartilhado, meia pensão','duration','flexible','week','USD',false,'2026-01-01','active') returning id into v_tpl;
    insert into price_tier (price_template_id, min_quantity, unit_price, sort) values (v_tpl,1,350.0,0);
    insert into price_template_product (price_template_id, product_id) values (v_tpl, v_pid);
    insert into fee (tenant_id, campus_id, name, fee_type, charge_basis, amount, currency, is_mandatory, is_refundable) values (v_tid,'4ff6d931-c7ac-5bcc-948a-0d3208e0c571','Taxa de colocação em acomodação','placement','once_per_item',160.0,'USD',true,false) returning id into v_fee;
    insert into fee_product (fee_id, product_id) values (v_fee, v_pid);
