    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Homestay da LSI: as famílias são selecionadas pelos Accommodation Officers da própria escola e visitadas com regularidade. Você pode escolher quarto individual (ou twin, quando duas pessoas reservam para o mesmo período) com café da manhã ou meia pensão. Roupa de cama e toalhas são fornecidas e trocadas semanalmente e o anfitrião oferece pelo menos uma lavagem de roupa por semana sem custo. Quem reserva só com café da manhã normalmente não tem acesso à cozinha. Há a opção Executive, com banheiro privativo (ensuite ou de uso exclusivo), mediante suplemento. Em San Diego, as famílias oferecem a experiência do estilo de vida californiano; os trajetos até a escola variam de 45 a 60 minutos e há lavanderia na casa ou em lavanderias locais por cerca de 5 dólares. Nesta opção você fica em quarto individual, com banheiro compartilhado com os demais moradores. O regime é de meia pensão, com café da manhã e jantar inclusos; o almoço fica por sua conta.</p><p>Suplementos e condições: Suplemento de alta temporada: USD 40/semana (14/jun a 23/ago); Suplemento dieta especial: USD 50/semana; Outro suplemento: USD 60.</p><p>Suplementos da casa de família em LSI San Diego, por pessoa por semana: verão de 14/jun a 23/ago US$40; Natal (fins de semana de 26-27/dez e 2-3/jan) US$60; dieta especial US$25 com café da manhã e US$50 com meia pensão; quarto executivo com banheiro privativo US$90; menores de 18 anos US$20. Taxa de colocação da acomodação US$160. Taxa de inscrição da escola US$185, envio de documentos por courier US$100, seguro-saúde US$40 por semana, transfer do aeroporto US$170 somente ida. Chegadas e saídas de sábado a sábado ou de domingo a domingo. Os preços da acomodação podem mudar ao longo do ano — confirme com a LSI San Diego na hora da reserva. Fonte: LSI Prices and Dates 2026.</p>','["Famílias Selecionadas e Visitadas pela Escola", "Roupa de Cama e Toalhas Trocadas Semanalmente", "1 Lavagem de Roupa por Semana Inclusa", "Quarto Individual ou Twin", "Imersão Cultural", "Prática Diária de Inglês", "Opção Executive com Banheiro Privativo", "Chegadas aos Sábados ou Domingos", "Quarto Individual", "Banheiro Compartilhado", "Meia Pensão", "Ideal para quem quer imersão cultural e prática diária de inglês", "Ideal para quem prefere ter refeições resolvidas em casa", "Ideal para quem viaja sozinho e quer apoio de anfitriões locais", "Ideal para quem busca bom custo-benefício com serviços inclusos", "Ideal para quem quer privacidade no quarto pagando menos que uma suíte", "Ideal para quem não se incomoda em dividir o banheiro", "Ideal para quem quer café da manhã e jantar garantidos e economia no dia a dia"]'::jsonb,'["Menos indicado para quem quer cozinhar livremente (sobretudo no regime só com café da manhã)", "Menos indicado para quem precisa morar a poucos minutos da escola", "Menos indicado para quem quer liberdade total de horários e visitas", "Menos indicado para quem prefere a vida social de uma residência estudantil", "Menos indicado para quem faz questão de banheiro exclusivo", "Menos indicado para quem tem horários muito rígidos de banho e rotina", "Menos indicado para quem tem horários irregulares e prefere jantar fora com frequência"]'::jsonb);
